#include <CGAL/Regular_triangulation_3.h>
#include <vector>
using K = CGAL::Exact_predicates_inexact_constructions_kernel;
using RT = CGAL::Regular_triangulation_3<K>;
typedef RT::Bare_point Point;

template <typename P, typename I>
struct Mesh {
    std::vector<P> vertices;
    std::vector<unsigned> data;
    std::vector<unsigned> sizes;
    std::vector<I> info;

    size_t size() const { return sizes.size(); }
    void push_back(const std::vector<unsigned>& vertices, const I& i) {
        data.insert(data.end(), vertices.begin(), vertices.end());
        sizes.push_back(vertices.size());
        info.push_back(i);
    }
};

inline bool is_small_edge(const RT& rt, const RT::Edge& e, double threshold) {
    double l = rt.segment(e).squared_length();
    return l < threshold;
}

Mesh<Point, double> power_diagram_faces(const RT& rt, double threshold) {
    Mesh<Point, double> result;

    for (RT::Cell_iterator cit = rt.finite_cells_begin(); cit != rt.finite_cells_end(); ++cit) {
        if (rt.is_infinite(cit)) continue;

        std::vector<unsigned> face;
        Point center = rt.dual(cit);

        for (int i = 0; i < 4; ++i) {
            RT::Cell_handle neighbor = cit->neighbor(i);
            if (rt.is_infinite(neighbor)) continue;

            RT::Edge edge(cit, i, (i+1)%4);
            if (!is_small_edge(rt, edge, threshold)) {
                face.push_back(result.vertices.size());
                result.vertices.push_back(center);
                break;
            }
        }

        if (!face.empty()) {
            result.push_back(face, 0.0);
        }
    }

    return result;
}

int main() {
    RT rt;
    Mesh<Point, double> mesh = power_diagram_faces(rt, 1.0);
    return 0;
}

